import urllib.request
for base in ['https://pmc.ncbi.nlm.nih.gov/articles/PMC7222625/bin/','https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7222625/bin/']:
    for f in ['NIHMS1574796-supplement-3.xlsx','NIHMS1574796-supplement-2.pdf']:
        url=base+f
        try:
            req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
            with urllib.request.urlopen(req) as r: data=r.read()
            print('OK', url, len(data), data[:8])
            open('/workspace/'+f,'wb').write(data)
        except Exception as e:
            print('ERR', url, e)
PY"

